namespace JingDll {
 public class Import { public string Name; public List<string> Symbols=new List<string>(); public bool Delay; }
 public class Pe {
  public string Architecture, Path; public bool IsDll, Managed, Prefer32Bit; public List<Import> Imports=new List<Import>(); public HashSet<string> Exports=new HashSet<string>(StringComparer.Ordinal);
  byte[] data; int opt, sections, count; bool plus;
  void Bounds(int p,int n){if(p<0||n<0||p>data.Length-n)throw new InvalidDataException("PE 数据越界或截断");}
  ushort U16(int p){Bounds(p,2);return BitConverter.ToUInt16(data,p);} uint U32(int p){Bounds(p,4);return BitConverter.ToUInt32(data,p);} ulong U64(int p){Bounds(p,8);return BitConverter.ToUInt64(data,p);}
  int Rva(uint r){if(r==0) return -1; for(int i=0;i<count;i++){int s=sections+i*40;uint va=U32(s+12),sz=Math.Max(U32(s+8),U32(s+16));if(r>=va&&(ulong)r<(ulong)va+sz){long p=(long)U32(s+20)+r-va;if(p>Int32.MaxValue)break;Bounds((int)p,1);return(int)p;}} if(r<U32(opt+60)){Bounds((int)r,1);return(int)r;}throw new InvalidDataException("无效 PE RVA");}
  string Str(int p){Bounds(p,1);int e=p;while(e<data.Length&&e-p<16384&&data[e]!=0)e++;if(e==data.Length||e-p==16384)throw new InvalidDataException("无效 PE 字符串");return Encoding.ASCII.GetString(data,p,e-p);}
  uint Dir(int n){int p=opt+(plus?112:96)+n*8;return U32(p);}
  public static Pe Read(string file){var p=new Pe();p.Path=file;var fi=new FileInfo(file);if(fi.Length<64||fi.Length>268435456)throw new InvalidDataException("仅支持 64 字节至 256 MB 的 PE 文件");p.data=File.ReadAllBytes(file);p.Parse();return p;}
  void Parse(){if(U16(0)!=0x5a4d)throw new InvalidDataException("文件不是有效的 Windows PE");int pe=checked((int)U32(60));if(U32(pe)!=0x4550)throw new InvalidDataException("无效 PE 签名");ushort machine=U16(pe+4);Architecture=machine==0x8664?"x64":machine==0x14c?"x86":machine==0xaa64?"ARM64":"Other";count=U16(pe+6);if(count>96)throw new InvalidDataException("PE 节数量异常");IsDll=(U16(pe+22)&0x2000)!=0;opt=pe+24;ushort magic=U16(opt);if(magic!=0x10b&&magic!=0x20b)throw new InvalidDataException("不支持的 PE 格式");plus=magic==0x20b;int optSize=U16(pe+20);if(optSize<(plus?240:224))throw new InvalidDataException("可选头不完整");sections=opt+optSize;Bounds(sections,count*40);Managed=Dir(14)!=0;
   if(Managed){uint flags=U32(Rva(Dir(14))+16);Prefer32Bit=(flags&0x20000)!=0;if(machine==0x14c&&(flags&1)!=0&&(flags&2)==0)Architecture="AnyCPU";}
   ReadImports(Dir(1),false);ReadImports(Dir(13),true);uint exp=Dir(0);if(exp!=0){int e=Rva(exp);uint ord=U32(e+16),nf=U32(e+20),nn=U32(e+24);if(nf>200000||nn>200000)throw new InvalidDataException("导出表过大");int funcs=Rva(U32(e+28));for(uint i=0;i<nf;i++)if(U32(funcs+checked((int)i*4))!=0)Exports.Add("#"+(ord+i));if(nn>0){int names=Rva(U32(e+32));for(uint i=0;i<nn;i++)Exports.Add(Str(Rva(U32(names+checked((int)i*4)))));}}
  }
  void ReadImports(uint addr,bool delay){if(addr==0)return;int start=Rva(addr),width=delay?32:20;for(int i=0;i<4096;i++){int d=start+i*width;Bounds(d,width);uint name=U32(d+(delay?4:12));if(name==0)return;if(delay&&(U32(d)&1)==0)throw new InvalidDataException("不支持旧式 VA 延迟导入表");string n=Str(Rva(name));if(System.IO.Path.GetFileName(n)!=n||!n.EndsWith(".dll",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("导入模块名无效");var im=new Import{Name=n,Delay=delay};uint thunk=U32(d+(delay?16:0));if(thunk==0)thunk=U32(d+(delay?12:16));if(thunk!=0){int t=Rva(thunk);for(int j=0;j<65536;j++){ulong v=plus?U64(t+j*8):U32(t+j*4);if(v==0)break;ulong mask=plus?0x8000000000000000UL:0x80000000UL;im.Symbols.Add((v&mask)!=0?"#"+(v&65535):Str(Rva(checked((uint)v))+2));if(j==65535)throw new InvalidDataException("导入表缺少结束符");}}Imports.Add(im);}throw new InvalidDataException("导入表过大");}
 }
 public class Finding {public string Dll{get;set;}public string Status{get;set;}public string Arch{get;set;}public string Version{get;set;}public string Location{get;set;}public string Detail{get;set;}public bool Problem{get;set;}}
 public class CatalogRow{public string Name{get;set;}public string Architecture{get;set;}public string Version{get;set;}public string Category{get;set;}public string Description{get;set;}public string Source{get;set;}}
 public class RepairRecord{public string Status{get;set;}public string Id{get;set;}public string Target{get;set;}public string Backup{get;set;}public string BeforeHash{get;set;}public string AfterHash{get;set;}public string Time{get;set;}public bool RolledBack{get;set;}}
 public static class Engine {
  public static string Home=System.IO.Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"JingDll");
  public const string GitHubUrl="https://github.com/jingpanlong/JingDll";
  public static string Hash(string p){using(var s=File.OpenRead(p))using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(s)).Replace("-","").ToLowerInvariant();}
  public static void Log(string text){Directory.CreateDirectory(Home);lock(logLock)File.AppendAllText(System.IO.Path.Combine(Home,"activity.log"),DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+"  "+text+Environment.NewLine,Encoding.UTF8);} static object logLock=new object();
  public static List<CatalogRow> Catalog(){var list=new List<CatalogRow>();using(var s=typeof(Engine).Assembly.GetManifestResourceStream("catalog.tsv"))using(var r=new StreamReader(s,Encoding.UTF8)){r.ReadLine();string line;while((line=r.ReadLine())!=null){var v=line.Split('\t');if(v.Length>=6)list.Add(new CatalogRow{Name=v[0],Architecture=v[1],Version=v[2],Category=v[3],Description=v[4],Source=v[5]});}}return list;}
  public static string EffectiveArchitecture(Pe pe){return pe.Architecture=="AnyCPU"?(pe.Prefer32Bit||!Environment.Is64BitOperatingSystem?"x86":"x64"):pe.Architecture;}
  public static List<Finding> Scan(string file,Action<string> progress){var pe=Pe.Read(file);string effective=EffectiveArchitecture(pe);var list=new List<Finding>();string app=System.IO.Path.GetDirectoryName(file);string win=Environment.GetFolderPath(Environment.SpecialFolder.Windows);string sys=System.IO.Path.Combine(win,effective=="x86"&&Environment.Is64BitOperatingSystem?"SysWOW64":"System32");
   foreach(var im in pe.Imports){progress(im.Name);var f=new Finding{Dll=im.Name,Arch=effective,Version="—",Location="—",Detail=(pe.Architecture=="AnyCPU"?"AnyCPU：按当前系统推断 "+effective+"，托管 DLL 实际架构由宿主决定。 ":"")+(im.Delay?"延迟导入；仅使用此功能时加载。 ":"")+"导入符号 "+im.Symbols.Count};
    if(im.Name.StartsWith("api-ms-",StringComparison.OrdinalIgnoreCase)||im.Name.StartsWith("ext-ms-",StringComparison.OrdinalIgnoreCase)){f.Status="API Set 合约";f.Detail+="；由操作系统映射，不能按同名文件是否存在判定缺失。";list.Add(f);continue;}
    var dirs=new[]{app,sys,win}.Concat((Environment.GetEnvironmentVariable("PATH")??"").Split(';').Where(x=>!String.IsNullOrWhiteSpace(x)&&System.IO.Path.IsPathRooted(x.Trim('"'))).Select(x=>x.Trim('"')));
    string located=null;foreach(var dir in dirs){try {string p=System.IO.Path.Combine(dir,im.Name);if(File.Exists(p)){located=p;break;}}catch{}}
    if(located==null){f.Status=im.Delay?"可选依赖待确认":"未找到候选文件";f.Problem=!im.Delay;f.Detail+="；需结合应用清单、SxS、加载器设置确认。";}
    else{f.Location=located;try{var dep=Pe.Read(located);f.Arch=dep.Architecture;f.Version=FileVersionInfo.GetVersionInfo(located).FileVersion??"—";var missing=im.Symbols.Where(x=>!dep.Exports.Contains(x)).ToList();if(dep.Architecture!=effective){f.Status="架构冲突";f.Problem=true;}else if(missing.Count>0){f.Status="缺少导出函数";f.Problem=true;f.Detail+="；未提供："+String.Join(", ",missing.Take(12));}else{f.Status="静态检查通过";f.Detail+="；未执行 DLL，未验证运行时加载。";}}catch(Exception ex){f.Status="文件异常";f.Problem=true;f.Detail+="；"+ex.Message;}}list.Add(f);
   }Log("依赖扫描完成："+file+"；直接依赖 "+list.Count+"；疑点 "+list.Count(x=>x.Problem));return list;
  }
  public static bool IsProtected(string p){string full=System.IO.Path.GetFullPath(p);var roots=new[]{Environment.GetFolderPath(Environment.SpecialFolder.Windows),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles),Environment.GetFolderPath(Environment.SpecialFolder.ProgramFilesX86),Home};return roots.Where(x=>!String.IsNullOrEmpty(x)).Any(x=>full.Equals(x,StringComparison.OrdinalIgnoreCase)||full.StartsWith(x.TrimEnd('\\')+"\\",StringComparison.OrdinalIgnoreCase));}
  static string RecordPath {get{return System.IO.Path.Combine(Home,"repairs.json");}}
  public static List<RepairRecord> Records(){if(!File.Exists(RecordPath))return new List<RepairRecord>();return new JavaScriptSerializer().Deserialize<List<RepairRecord>>(File.ReadAllText(RecordPath,Encoding.UTF8))??new List<RepairRecord>();}
  static void SaveRecords(List<RepairRecord> records){Directory.CreateDirectory(Home);string tmp=RecordPath+".tmp";File.WriteAllText(tmp,new JavaScriptSerializer().Serialize(records),Encoding.UTF8);if(File.Exists(RecordPath))File.Replace(tmp,RecordPath,null);else File.Move(tmp,RecordPath);}
  public static RepairRecord Replace(string application,string source){string folder=System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(application));string name=System.IO.Path.GetFileName(source);if(IsProtected(folder))throw new InvalidOperationException("仅支持用户应用目录；Windows、Program Files 和工具自身数据目录请使用官方安装/修复。" );if(IsSystemContract(name))throw new InvalidOperationException("Windows KnownDLLs 与 API Set 请使用官方系统修复，不能通过应用目录替换。");var app=Pe.Read(application);var dll=Pe.Read(source);if(!dll.IsDll||dll.Architecture!=EffectiveArchitecture(app))throw new InvalidOperationException("DLL 类型或处理器架构与目标程序不一致。");var required=app.Imports.Where(x=>String.Equals(x.Name,name,StringComparison.OrdinalIgnoreCase)).ToList();if(required.Count==0)throw new InvalidOperationException("此文件不是目标程序的直接导入依赖。");var missing=required.SelectMany(x=>x.Symbols).Where(x=>!dll.Exports.Contains(x)).ToList();if(missing.Count>0)throw new InvalidOperationException("替换文件缺少所需导出函数："+String.Join(", ",missing.Take(8)));
   string target=System.IO.Path.Combine(folder,name);if(String.Equals(System.IO.Path.GetFullPath(source),target,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("来源文件与目标文件相同。");RejectReparse(folder);RejectReparse(source);if(File.Exists(target))RejectReparse(target);
   string id=Guid.NewGuid().ToString("N"),backupDir=System.IO.Path.Combine(Home,"Backups",id);Directory.CreateDirectory(backupDir);var rec=new RepairRecord{Status="准备就绪",Id=id,Target=target,Time=DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"),AfterHash=Hash(source),Backup="",BeforeHash=""};if(File.Exists(target)){rec.Backup=System.IO.Path.Combine(backupDir,"original.dll");File.Copy(target,rec.Backup);rec.BeforeHash=Hash(rec.Backup);}var all=Records();all.Add(rec);SaveRecords(all);string staging=System.IO.Path.Combine(folder,".jingdll-"+id+".tmp");try{File.Copy(source,staging);if(Hash(staging)!=rec.AfterHash)throw new IOException("暂存文件校验失败");if(File.Exists(target))File.Replace(staging,target,null);else File.Move(staging,target);rec.Status="已部署";SaveRecords(all);}catch{rec.Status="未部署 / 需核查";SaveRecords(all);throw;}finally{if(File.Exists(staging))File.Delete(staging);}Log("应用 DLL 替换："+target+"；备份编号 "+id);return rec;
  }
  public static void Rollback(RepairRecord rec){if(rec.RolledBack)throw new InvalidOperationException("该记录已回滚");if(IsProtected(rec.Target)||!rec.Id.All(Uri.IsHexDigit)||rec.Id.Length!=32)throw new InvalidOperationException("回滚记录无效");RejectReparse(System.IO.Path.GetDirectoryName(rec.Target));if(!File.Exists(rec.Target)||Hash(rec.Target)!=rec.AfterHash)throw new InvalidOperationException("目标文件已被其他程序更改或删除，为防止覆盖，已停止回滚。");RejectReparse(rec.Target);if(!String.IsNullOrEmpty(rec.Backup)){string expected=System.IO.Path.Combine(Home,"Backups",rec.Id,"original.dll");if(!String.Equals(expected,rec.Backup,StringComparison.OrdinalIgnoreCase)||Hash(rec.Backup)!=rec.BeforeHash)throw new InvalidOperationException("备份校验失败");string tmp=rec.Target+".rollback-"+rec.Id;File.Copy(rec.Backup,tmp,false);try{File.Replace(tmp,rec.Target,null);}finally{if(File.Exists(tmp))File.Delete(tmp);}}else File.Delete(rec.Target);var records=Records();var item=records.FirstOrDefault(x=>x.Id==rec.Id);if(item!=null){item.RolledBack=true;item.Status="已回滚";}SaveRecords(records);Log("回滚完成："+rec.Target);}
  public static void RejectReparse(string path){string cur=System.IO.Path.GetFullPath(path);while(!String.IsNullOrEmpty(cur)){if((File.GetAttributes(cur)&FileAttributes.ReparsePoint)!=0)throw new InvalidOperationException("不支持符号链接或目录联接中的修复操作");cur=System.IO.Path.GetDirectoryName(cur);}}
  public static bool IsSystemContract(string name){if(name.StartsWith("api-ms-",StringComparison.OrdinalIgnoreCase)||name.StartsWith("ext-ms-",StringComparison.OrdinalIgnoreCase))return true;using(var key=Registry.LocalMachine.OpenSubKey(@"SYSTEM\CurrentControlSet\Control\Session Manager\KnownDLLs")){if(key!=null)foreach(string entry in key.GetValueNames())if(String.Equals(Convert.ToString(key.GetValue(entry)),name,StringComparison.OrdinalIgnoreCase))return true;}return false;}
  public static void ValidateMicrosoftPackage(string path){if(!Trust.Verify(path))throw new InvalidDataException("安装包签名校验未通过，已停止执行。");using(var cert=new X509Certificate2(X509Certificate.CreateFromSignedFile(path))){if(!cert.GetNameInfo(X509NameType.SimpleName,false).Equals("Microsoft Corporation",StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("安装包发布者不是 Microsoft Corporation。");}}
  public static string Signature(string p){return Trust.Verify(p)?"有效的 Authenticode 签名":"无有效 Authenticode 签名（可能未签名、信任链不可用或校验失败）";}
  public static string Inspect(string p){var pe=Pe.Read(p);var v=FileVersionInfo.GetVersionInfo(p);return "文件："+p+"\r\n架构："+pe.Architecture+(pe.Managed?" / 含 CLR 元数据（AnyCPU 需结合 CLR 标志判断）":"")+"\r\n类型："+(pe.IsDll?"DLL":"EXE")+"\r\n版本："+v.FileVersion+"\r\n产品："+v.ProductName+"\r\n公司："+v.CompanyName+"\r\n签名："+Signature(p)+"\r\nSHA-256："+Hash(p)+"\r\n直接导入模块："+pe.Imports.Count+"\r\n导出符号（含序号）："+pe.Exports.Count+"\r\n\r\n"+String.Join("\r\n",pe.Imports.Select(x=>x.Name+"  ["+x.Symbols.Count+" 个符号]"+(x.Delay?" 延迟":"")));}
 }
 public static class Trust {
  [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]class FileInfoNative {public uint cbStruct=(uint)Marshal.SizeOf(typeof(FileInfoNative));[MarshalAs(UnmanagedType.LPWStr)]public string pcwszFilePath;public IntPtr hFile=IntPtr.Zero;public IntPtr pgKnownSubject=IntPtr.Zero;}
  [StructLayout(LayoutKind.Sequential,CharSet=CharSet.Unicode)]class TrustData {public uint cbStruct=(uint)Marshal.SizeOf(typeof(TrustData));public IntPtr pPolicyCallbackData=IntPtr.Zero,pSIPClientData=IntPtr.Zero;public uint dwUIChoice=2,fdwRevocationChecks=0,dwUnionChoice=1;public IntPtr pFile;public uint dwStateAction=0;public IntPtr hWVTStateData=IntPtr.Zero;public IntPtr pwszURLReference=IntPtr.Zero;public uint dwProvFlags=0x1000,dwUIContext=0;}
  [DllImport("wintrust.dll",ExactSpelling=true,PreserveSig=true)]static extern int WinVerifyTrust(IntPtr hwnd,[MarshalAs(UnmanagedType.LPStruct)]Guid action,TrustData data);
  public static bool Verify(string path){var fi=new FileInfoNative{pcwszFilePath=System.IO.Path.GetFullPath(path)};IntPtr ptr=Marshal.AllocHGlobal(Marshal.SizeOf(fi));try{Marshal.StructureToPtr(fi,ptr,false);return WinVerifyTrust(new IntPtr(-1),new Guid("00AAC56B-CD44-11d0-8CC2-00C04FC295EE"),new TrustData{pFile=ptr})==0;}finally{Marshal.DestroyStructure(ptr,typeof(FileInfoNative));Marshal.FreeHGlobal(ptr);}}
 }
